function lockAccess(data){if(lockedLogin)return;cleanupCamera();lockedLogin=data.login;lockContent=document.createDocumentFragment();if($('#modal').open){$$('input[type=password]',$('#modal-content')).forEach(i=>i.value='');while($('#modal-content').firstChild)lockContent.append($('#modal-content').firstChild);}openModal('Acceso bloqueado',`<p>Tu trabajo permanece abierto. Confirma el PIN de ${esc(data.name)} para continuar.</p><form id="unlock-form"><label class="gap-top">PIN personal<input name="password" type="password" inputmode="numeric" pattern="[0-9]{6,12}" required maxlength="12" autocomplete="current-password"></label><div class="modal-actions"><button class="primary" type="submit">Continuar trabajando</button></div></form>`);$('[data-action="close-modal"]',$('#modal-content')).hidden=true;}

async function request(path,body) {
  const method=body===undefined?'GET':'POST',activity=interactionVersion,headers={'X-Client':clientId,'X-Activity':activity>acknowledgedActivity?'1':'0'}; let pendingKey,pendingSecret;
  if(body!==undefined){headers['Content-Type']='application/json';headers['X-CSRF']=csrf;
    if(path!=='login'&&path!=='unlock'&&path!=='logout'&&!['users','user-update','backup','restore','cancel-entry','cancel-wash'].includes(path)){
      const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(path+'\n'+JSON.stringify(body)));
      pendingKey='oeste-pending-'+Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');
      let key=sessionStorage.getItem(pendingKey);if(!key){key=uuid();sessionStorage.setItem(pendingKey,key);}headers['Idempotency-Key']=key;
    }
    if(['users','user-update','cancel-entry','cancel-wash'].includes(path)){pendingSecret=path+'\n'+JSON.stringify(body);let key=secretPending.get(pendingSecret);if(!key){key=uuid();secretPending.set(pendingSecret,key);}headers['Idempotency-Key']=key;}
  }
  if(body!==undefined&&!headers['Idempotency-Key']&&path!=='login'&&path!=='unlock'&&path!=='logout')headers['Idempotency-Key']=uuid();
  let response;try{response=await fetch('/api/'+path,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout?AbortSignal.timeout(['backup','restore'].includes(path)?120000:['users','user-update','cancel-entry','cancel-wash'].includes(path)?60000:20000):undefined});}
  catch(e){$('#connection-error').hidden=false;if(['users','user-update','cancel-entry','cancel-wash'].includes(path)&&(e.name==='TimeoutError'||e.name==='AbortError'))throw new Error('La tablet está tardando. Reintenta sin cambiar los datos: se consultará la misma operación, sin duplicarla.');throw new Error('No se recibió confirmación. Reconecta y reintenta esta misma operación; conserva su identificador para evitar duplicados.');}
  const data=await response.json();if(response.status<500){if(pendingKey)sessionStorage.removeItem(pendingKey);if(pendingSecret)secretPending.delete(pendingSecret);}
  if(response.status===423){lockAccess(data);throw new Error(data.error);}if(response.ok)acknowledgedActivity=Math.max(acknowledgedActivity,activity);
  if(response.status===401&&!['login','unlock'].includes(path)){showLogin();throw new Error('La sesión terminó. Vuelve a ingresar.');}
  if(!response.ok)throw new Error(data.error||'No se pudo completar la operación.');$('#connection-error').hidden=true;return data;
}
