function heading(eyebrow,title,subtitle,action=''){const back=['pensiones','reportes','tarjetas','ajustes','respaldos','actualizaciones','equipo'].includes(tab)?`<button class="back-link" data-tab="admin">${icon('back')} Administración</button>`:'';return `<div class="page-heading row spread"><div>${back}<p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="big">${icon('car')}</div><h3>${title}</h3><p>${text}</p>${action}</div>`;}
